(() => {
  const results = {
    apiUrls: new Set(),
    supabaseEndpoints: new Set(),
    externalDomains: new Set(),
    serviceNames: new Set()
  };

  // Search all HTML for URLs
  const html = document.documentElement.innerHTML;
  const urlRegex = /https?:\/\/[^\s\"'<>]+/g;
  let m;
  while ((m = urlRegex.exec(html)) !== null) {
    const url = m[1] || m[0];
    try {
      const u = new URL(url);
      if (!u.hostname.includes('mobility.xtend.co') && !u.hostname.includes('localhost')) {
        results.externalDomains.add(u.hostname);
      }
    } catch(e) {}
  }

  // Search scripts
  const scripts = Array.from(document.querySelectorAll('script'));
  scripts.forEach(s => {
    const src = s.src;
    if (src) {
      try {
        const u = new URL(src);
        results.externalDomains.add(u.hostname);
      } catch(e) {}
    }
    if (s.textContent) {
      const matches = s.textContent.match(/https?:\/\/[^\s\"'<>]+/g);
    if (matches) {
        matches.forEach(url => {
          try {
            const u = new URL(url);
            if (!u.hostname.includes('mobility.xtend.co')) {
              results.externalDomains.add(u.hostname);
            }
          } catch(e) {}
        });
      }
    }
  });

  // Search for service names in text
  const bodyText = document.body.innerText.toLowerCase();
  const services = ['wesbank','flickswitch','supabase','openstreetmap','google','cdnjs','jsdelivr','leaflet','jspdf','pdf.js','xlsx','fatima','natasha','ecosystem','xtend','dash.xtend'];
  services.forEach(s => {
    if (bodyText.includes(s)) results.serviceNames.add(s);
  });

  return JSON.stringify({
    externalDomains: Array.from(results.externalDomains).sort(),
    serviceNames: Array.from(results.serviceNames).sort()
  });
})()
